import os
import csv
from openpyxl import load_workbook


def task_func(file_name, excel_file_path, csv_file_path) -> str:
    source_path = excel_file_path or file_name
    if not source_path:
        raise ValueError("An Excel file path must be provided.")

    if not csv_file_path:
        base_name = os.path.splitext(os.path.basename(file_name or source_path))[0] + ".csv"
        csv_file_path = os.path.join(os.path.dirname(source_path), base_name)

    output_dir = os.path.dirname(csv_file_path)
    if output_dir:
        os.makedirs(output_dir, exist_ok=True)

    def iter_rows():
        ext = os.path.splitext(source_path)[1].lower()

        if ext == ".xls":
            try:
                import xlrd

                workbook = xlrd.open_workbook(source_path)
                active_index = getattr(workbook, "active_sheet", 0)
                if not isinstance(active_index, int) or not (0 <= active_index < workbook.nsheets):
                    active_index = 0

                sheet = workbook.sheet_by_index(active_index)
                for row_idx in range(sheet.nrows):
                    yield sheet.row_values(row_idx)
                return
            except Exception:
                pass

        workbook = load_workbook(source_path, read_only=True, data_only=True)
        try:
            sheet = workbook.active
            for row in sheet.iter_rows(values_only=True):
                yield row
        finally:
            workbook.close()

    with open(csv_file_path, "w", newline="", encoding="utf-8-sig") as csv_file:
        writer = csv.writer(csv_file)
        for row in iter_rows():
            writer.writerow(list(row) if row is not None else [])

    return os.path.basename(csv_file_path)
